  for(const item of ["Magazine","Authors","Podcast"]){
    const cell=auto("VERTICAL",6);cell.counterAxisAlignItems="CENTER";cell.name="Nav_"+item;
    const t=await T(item,16,current===item?"Bold":"Medium",current===item?BLACK:GRAY,{name:"Label"});
    cell.appendChild(t);
    const ul=rect(40,2,BLACK);ul.name="Underline";ul.visible=(current===item);
    cell.appendChild(ul);
    nav.appendChild(cell);
  }
  const soc=auto("HORIZONTAL",20);soc.name="Social";h.appendChild(soc);
  for(const k of ["ig","tw","yt","rss"]){soc.appendChild(await icon(k,20,BLACK));}
  // layout: wordmark left, nav center, social right -> use spacers
  h.layoutAlign; 
  h.primaryAxisSizingMode="FIXED";
  // insert spacers
  const sp1=rect(10,10);sp1.fills=[];sp1.layoutGrow=1;sp1.name="sp1";
