  const wrap=figma.createFrame();wrap.resize(1680,96);wrap.fills=[];wrap.clipsContent=true;
  wrap.appendChild(h);wrap.appendChild(bottom);bottom.x=0;bottom.y=95;
  return comp("Header",wrap,1680,96);
}
