const solid=c=>[{type:"SOLID",color:c}];
async function T(chars,size,style,color,opts={}){const t=figma.createText();t.fontName={family:"Hanken Grotesk",style};t.fontSize=size;t.characters=chars;t.fills=solid(color||BLACK);if(opts.ls)t.letterSpacing={value:opts.ls,unit:"PIXELS"};if(opts.lh)t.lineHeight={value:opts.lh,unit:"PIXELS"};if(opts.name)t.name=opts.name;if(opts.align)t.textAlignHorizontal=opts.align;return t;}
function auto(dir,spacing){const f=figma.createFrame();f.layoutMode=dir;f.itemSpacing=spacing||0;f.primaryAxisSizingMode="AUTO";f.counterAxisSizingMode="AUTO";f.fills=[];return f;}
function rect(w,h,c){const r=figma.createRectangle();r.resize(w,h);r.fills=c?solid(c):[];return r;}
function spacer(){const s=rect(10,10);s.layoutGrow=1;s.name="spacer";return s;}
const ICONS={diag:"1:91",left:"1:92",right:"1:93",ig:"1:94",rss:"1:95",tw:"1:96",yt:"1:97"};
async function icon(key,size,color){const c=await figma.getNodeByIdAsync(ICONS[key]);const i=c.createInstance();i.resize(size,size);if(color){for(const ch of i.findAll(n=>n.type==="VECTOR"||n.type==="BOOLEAN_OPERATION")){try{ch.fills=solid(color);}catch(e){}}}return i;}
function comp(name,node){node.name=name;const c=figma.createComponentFromNode(node);c.name=name;return c;}

