// ---------- Header variants ----------
async function buildHeader(current){
  const wrap=figma.createFrame();wrap.resize(1680,96);wrap.fills=solid(WHITE);wrap.clipsContent=true;
  const h=auto("HORIZONTAL",0);h.counterAxisSizingMode="FIXED";h.resize(1680,96);h.primaryAxisSizingMode="FIXED";
  h.paddingLeft=80;h.paddingRight=80;h.counterAxisAlignItems="CENTER";
  h.appendChild(await T("FYRRE MAGAZINE",20,"ExtraBold",BLACK,{ls:2,name:"Wordmark"}));
  h.appendChild(spacer());
  const nav=auto("HORIZONTAL",40);nav.name="Nav";h.appendChild(nav);
  for(const item of ["Magazine","Authors","Podcast"]){
    const cell=auto("VERTICAL",6);cell.counterAxisAlignItems="CENTER";cell.name="Nav_"+item;
    cell.appendChild(await T(item,16,current===item?"Bold":"Medium",current===item?BLACK:GRAY,{name:"Label"}));
    const ul=rect(40,2,BLACK);ul.name="Underline";ul.visible=(current===item);
    cell.appendChild(ul);
    nav.appendChild(cell);
  }
  h.appendChild(spacer());
  const soc=auto("HORIZONTAL",20);soc.name="Social";h.appendChild(soc);
  for(const k of ["ig","tw","yt","rss"]){soc.appendChild(await icon(k,20,BLACK));}
  wrap.appendChild(h);
  const bottom=rect(1680,1,RULE);bottom.x=0;bottom.y=95;bottom.name="Border";
  wrap.appendChild(bottom);
  return wrap;
}
const variants=[];
for(const v of ["None","Magazine","Authors","Podcast"]){
  const c=comp("Header",await buildHeader(v));
  c.variantProperties={Current:v};
  variants.push(c);
}
const headerSet=figma.combineAsVariants(variants,figma.currentPage);
headerSet.name="Header";headerSet.x=-4400;headerSet.y=-2600;
created.push("Header: "+headerSet.id);

